from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    exterior = set()
    queue = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c))
                queue.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c))
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background
                    and (nr, nc) not in exterior):
                exterior.add((nr, nc))
                queue.append((nr, nc))

    out = [row[:] for row in grid]
    seen = set(exterior)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            queue = deque([(r, c)])
            seen.add((r, c))
            component = []
            while queue:
                y, x = queue.popleft()
                component.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == background
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        queue.append((ny, nx))
            r0 = min(y for y, x in component)
            r1 = max(y for y, x in component)
            c0 = min(x for y, x in component)
            c1 = max(x for y, x in component)
            if len(component) == (r1 - r0 + 1) * (c1 - c0 + 1):
                for y, x in component:
                    out[y][x] = 4
    return out

